-- Bands: a band is a group of talent profiles. It is not an account and has no username.
--
-- Generated by supabase/generators/import_groups.py from src/data/band.ts (via
-- supabase/generators/export_demo_groups.ts) and The Bangalore Blues Project profile. Edit the
-- generator, not this file.
--
-- Schema
--   bands          slug (URL key, not a username), name, tagline, bio, genres, city, formed year, avatar,
--                  cover, open seats, availability, rate (paise + unit), is_verified (admin-only, by
--                  trigger), created_by.
--   band_members   band + talent profile, role owner | admin | member (one owner), instrument, since.
--   band_events    shows: date (day or month precision), time, venue, city, confirmed | hold (past follows
--                  from the date), ticket note.
--   band_releases  single | ep | album | live, year, cover.
--   Read: everyone (members with their profile's visibility). Write: the creator and members; the
--   line-up is changed by the creator, owner and admins, and a member can leave.
--
-- Data
--   Demo bands: 2 (the-kite-notes, static-bloom), 4 shows, 3 releases. Genres are kept as
--   written in the demo (no taxonomy option matches them). Their 6 members join a profile only
--   where username and display name both match when this runs; a NOTICE lists the rest.
--   The Bangalore Blues Project (band slug the-bangalore-blues-project) from profile c2b4edcd-eb80-5a4f-86d8-35a2a5a88ad6:
--   name, headline, bio, city, genres, avatar and cover copied from the profile, its 3 shows copied
--   from profile_events. Line-up slots filled with existing talent profiles:
--   arnav.desai    Lead Vocalist & Slide Guitar (owner)
--   arjun.kapoor   Keyboards & Hammond B3 (member)
--   zara.desai     Alto Saxophone (member)
--   kabirmenon     Double Bass (member)
--   arnav.gupta    Drums & Percussion (member)
--   The profile, its username, line-up names, shows and portfolio are not changed or deleted.
--   Not stored: followers, QR codes, invitations, the demo portfolio item link.
--
-- Each data block re-reads what it wrote and raises on any difference. Idempotent: fixed uuid5 ids.
-- Rollback: DROP TABLE public.band_releases, public.band_events, public.band_members, public.bands;
--   DROP FUNCTION public.band_can_write(uuid), public.band_can_manage(uuid), public.band_is_owner(uuid),
--   public.bands_guard_admin_fields();

CREATE TABLE IF NOT EXISTS public.bands (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug         text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND length(slug) <= 60),
  name         text NOT NULL CHECK (length(name) BETWEEN 1 AND 80),
  tagline      text,
  bio          text,
  genres       text[] NOT NULL DEFAULT '{}',
  city         text,
  formed_year  int CHECK (formed_year BETWEEN 1900 AND 2100),
  avatar_url   text,
  cover_url    text,
  looking_for  text[] NOT NULL DEFAULT '{}',
  availability text CHECK (availability IN ('available', 'selective', 'booked')),
  rate_paise   bigint CHECK (rate_paise >= 0),
  rate_unit    text,
  is_verified  boolean NOT NULL DEFAULT false,
  created_by   uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.band_members (
  band_id    uuid NOT NULL REFERENCES public.bands(id) ON DELETE CASCADE,
  profile_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  role       text NOT NULL DEFAULT 'member' CHECK (role IN ('owner', 'admin', 'member')),
  instrument text,
  since_year int CHECK (since_year BETWEEN 1900 AND 2100),
  sort_order int NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (band_id, profile_id)
);
CREATE UNIQUE INDEX IF NOT EXISTS band_members_one_owner ON public.band_members (band_id) WHERE role = 'owner';
CREATE INDEX IF NOT EXISTS band_members_profile_idx ON public.band_members (profile_id);

CREATE TABLE IF NOT EXISTS public.band_events (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  band_id        uuid NOT NULL REFERENCES public.bands(id) ON DELETE CASCADE,
  title          text NOT NULL,
  venue          text,
  city           text,
  event_date     date,
  event_time     time,
  date_precision text NOT NULL DEFAULT 'day' CHECK (date_precision IN ('day', 'month')),
  status         text CHECK (status IN ('confirmed', 'hold')),
  ticket_note    text,
  sort_order     int NOT NULL DEFAULT 0,
  created_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS band_events_band_idx ON public.band_events (band_id, event_date);

CREATE TABLE IF NOT EXISTS public.band_releases (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  band_id      uuid NOT NULL REFERENCES public.bands(id) ON DELETE CASCADE,
  title        text NOT NULL,
  kind         text NOT NULL CHECK (kind IN ('single', 'ep', 'album', 'live')),
  release_year int CHECK (release_year BETWEEN 1900 AND 2100),
  cover_url    text,
  sort_order   int NOT NULL DEFAULT 0,
  created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS band_releases_band_idx ON public.band_releases (band_id, sort_order);

DROP TRIGGER IF EXISTS update_bands_updated_at ON public.bands;
CREATE TRIGGER update_bands_updated_at BEFORE UPDATE ON public.bands
  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

-- is_verified is granted by MusicLinkd: signed-in and anonymous callers cannot set or change it.
CREATE OR REPLACE FUNCTION public.bands_guard_admin_fields()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $fn$
BEGIN
  IF coalesce(auth.jwt() ->> 'role', '') IN ('authenticated', 'anon')
     AND ((TG_OP = 'INSERT' AND NEW.is_verified)
          OR (TG_OP = 'UPDATE' AND NEW.is_verified IS DISTINCT FROM OLD.is_verified)) THEN
    RAISE EXCEPTION 'is_verified is set by MusicLinkd, not by the band';
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS bands_guard_admin_fields ON public.bands;
CREATE TRIGGER bands_guard_admin_fields BEFORE INSERT OR UPDATE ON public.bands
  FOR EACH ROW EXECUTE FUNCTION public.bands_guard_admin_fields();

-- Who may write. SECURITY DEFINER so the policies can read band_members without recursing into its RLS.
CREATE OR REPLACE FUNCTION public.band_can_write(p_band_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $fn$
  SELECT auth.uid() IS NOT NULL AND (
    EXISTS (SELECT 1 FROM public.bands b WHERE b.id = p_band_id AND b.created_by = auth.uid())
    OR EXISTS (SELECT 1 FROM public.band_members m WHERE m.band_id = p_band_id AND m.profile_id = auth.uid()));
$fn$;

CREATE OR REPLACE FUNCTION public.band_can_manage(p_band_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $fn$
  SELECT auth.uid() IS NOT NULL AND (
    EXISTS (SELECT 1 FROM public.bands b WHERE b.id = p_band_id AND b.created_by = auth.uid())
    OR EXISTS (SELECT 1 FROM public.band_members m
               WHERE m.band_id = p_band_id AND m.profile_id = auth.uid() AND m.role IN ('owner', 'admin')));
$fn$;
CREATE OR REPLACE FUNCTION public.band_is_owner(p_band_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $fn$
  SELECT auth.uid() IS NOT NULL AND (
    EXISTS (SELECT 1 FROM public.bands b WHERE b.id = p_band_id AND b.created_by = auth.uid())
    OR EXISTS (SELECT 1 FROM public.band_members m
               WHERE m.band_id = p_band_id AND m.profile_id = auth.uid() AND m.role = 'owner'));
$fn$;
REVOKE ALL ON FUNCTION public.band_is_owner(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.band_is_owner(uuid) TO anon, authenticated;
REVOKE ALL ON FUNCTION public.band_can_write(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.band_can_manage(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.band_can_write(uuid) TO anon, authenticated;
GRANT EXECUTE ON FUNCTION public.band_can_manage(uuid) TO anon, authenticated;

DO $rls$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['bands', 'band_members', 'band_events', 'band_releases'] LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('GRANT SELECT ON public.%I TO anon, authenticated', t);
    EXECUTE format('GRANT INSERT, UPDATE, DELETE ON public.%I TO authenticated', t);
    EXECUTE format('GRANT ALL ON public.%I TO service_role', t);
  END LOOP;
END
$rls$;

-- bands: everyone reads; a signed-in person creates one as its creator; the creator and members edit;
-- the creator or the owner deletes.
DROP POLICY IF EXISTS "Readable by everyone" ON public.bands;
CREATE POLICY "Readable by everyone" ON public.bands FOR SELECT USING (true);
DROP POLICY IF EXISTS "Creators insert" ON public.bands;
CREATE POLICY "Creators insert" ON public.bands FOR INSERT TO authenticated WITH CHECK (created_by = auth.uid());
DROP POLICY IF EXISTS "Creator and members update" ON public.bands;
CREATE POLICY "Creator and members update" ON public.bands FOR UPDATE TO authenticated
  USING (public.band_can_write(id)) WITH CHECK (public.band_can_write(id));
DROP POLICY IF EXISTS "Creator and owner delete" ON public.bands;
CREATE POLICY "Creator and owner delete" ON public.bands FOR DELETE TO authenticated
  USING (public.band_is_owner(id));

-- band_members: readable with the member's profile; the creator, owner and admins change the line-up;
-- a member can leave.
DROP POLICY IF EXISTS "Readable with the member's profile" ON public.band_members;
CREATE POLICY "Readable with the member's profile" ON public.band_members FOR SELECT
  USING (public.profile_is_readable(profile_id));
DROP POLICY IF EXISTS "Managers add" ON public.band_members;
CREATE POLICY "Managers add" ON public.band_members FOR INSERT TO authenticated
  WITH CHECK (public.band_can_manage(band_id));
DROP POLICY IF EXISTS "Managers update" ON public.band_members;
CREATE POLICY "Managers update" ON public.band_members FOR UPDATE TO authenticated
  USING (public.band_can_manage(band_id)) WITH CHECK (public.band_can_manage(band_id));
DROP POLICY IF EXISTS "Managers remove, members leave" ON public.band_members;
CREATE POLICY "Managers remove, members leave" ON public.band_members FOR DELETE TO authenticated
  USING (public.band_can_manage(band_id) OR profile_id = auth.uid());

-- band_events, band_releases: everyone reads; the creator and members write.
DO $rls$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['band_events', 'band_releases'] LOOP
    EXECUTE format('DROP POLICY IF EXISTS "Readable by everyone" ON public.%I', t);
    EXECUTE format('CREATE POLICY "Readable by everyone" ON public.%I FOR SELECT USING (true)', t);
    EXECUTE format('DROP POLICY IF EXISTS "Creator and members write" ON public.%I', t);
    EXECUTE format('CREATE POLICY "Creator and members write" ON public.%I FOR ALL TO authenticated USING (public.band_can_write(band_id)) WITH CHECK (public.band_can_write(band_id))', t);
  END LOOP;
END
$rls$;

-- bands: demo bands (2 rows)
DO $import$
DECLARE
  payload jsonb := $json$[{"id":"1a18f576-c433-50ae-9be7-e1d22cad05bc","slug":"the-kite-notes","name":"The Kite Notes","tagline":"Indie-folk quartet from Bandra with a brass habit.","bio":"Four players, one room, everything tracked live. We tour the west-coast circuit and record between runs at Octave Sound Labs.","genres":["Indie Folk","Alt Pop"],"city":"Mumbai","formed_year":2019,"avatar_url":"https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?auto=format&fit=crop&w=400&q=80","cover_url":"https://images.unsplash.com/photo-1470229722913-7c0e2dbbafd3?auto=format&fit=crop&w=900&q=80","looking_for":["Touring drummer","Live sound engineer"],"availability":"selective","rate_paise":8500000,"rate_unit":"show","is_verified":true},{"id":"71573c4d-f836-5cfe-9ba1-02b246a57353","slug":"static-bloom","name":"Static Bloom","tagline":"Electronic trio building live-modular sets.","bio":"Modular rigs, no laptops on stage. Currently writing a first full-length.","genres":["Electronic","Ambient"],"city":"Bengaluru","formed_year":2022,"avatar_url":"https://images.unsplash.com/photo-1516280440614-37939bbacd81?auto=format&fit=crop&w=400&q=80","cover_url":"https://images.unsplash.com/photo-1516450360452-9312f5e86fc7?auto=format&fit=crop&w=900&q=80","looking_for":["Visual artist","Booking agent"],"availability":"available","rate_paise":4000000,"rate_unit":"show","is_verified":false}]$json$;
BEGIN
  INSERT INTO public.bands (id, slug, name, tagline, bio, genres, city, formed_year, avatar_url, cover_url, looking_for, availability, rate_paise, rate_unit, is_verified)
  SELECT r.id, r.slug, r.name, r.tagline, r.bio, r.genres, r.city, r.formed_year, r.avatar_url, r.cover_url, r.looking_for, r.availability, r.rate_paise, r.rate_unit, r.is_verified FROM jsonb_to_recordset(payload) AS r(id uuid, slug text, name text, tagline text, bio text, genres text[], city text, formed_year int, avatar_url text, cover_url text, looking_for text[], availability text, rate_paise bigint, rate_unit text, is_verified boolean)
  ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, name = EXCLUDED.name, tagline = EXCLUDED.tagline, bio = EXCLUDED.bio, genres = EXCLUDED.genres, city = EXCLUDED.city, formed_year = EXCLUDED.formed_year, avatar_url = EXCLUDED.avatar_url, cover_url = EXCLUDED.cover_url, looking_for = EXCLUDED.looking_for, availability = EXCLUDED.availability, rate_paise = EXCLUDED.rate_paise, rate_unit = EXCLUDED.rate_unit, is_verified = EXCLUDED.is_verified;

  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(id uuid, slug text, name text, tagline text, bio text, genres text[], city text, formed_year int, avatar_url text, cover_url text, looking_for text[], availability text, rate_paise bigint, rate_unit text, is_verified boolean) JOIN public.bands t ON t.id = r.id
      WHERE (t.id, t.slug, t.name, t.tagline, t.bio, t.genres, t.city, t.formed_year, t.avatar_url, t.cover_url, t.looking_for, t.availability, t.rate_paise, t.rate_unit, t.is_verified) IS NOT DISTINCT FROM (r.id, r.slug, r.name, r.tagline, r.bio, r.genres, r.city, r.formed_year, r.avatar_url, r.cover_url, r.looking_for, r.availability, r.rate_paise, r.rate_unit, r.is_verified))
     <> jsonb_array_length(payload) THEN
    RAISE EXCEPTION 'bands import: stored rows differ from the payload';
  END IF;
END
$import$;

-- bands: The Bangalore Blues Project, from its profile (1 rows)
DO $import$
DECLARE
  payload jsonb := $json$[{"id":"035dfe6b-04c5-5fcc-b41f-27e32a435685","slug":"the-bangalore-blues-project","source_profile_id":"c2b4edcd-eb80-5a4f-86d8-35a2a5a88ad6"}]$json$;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM jsonb_to_recordset(payload) AS r(id uuid, slug text, source_profile_id uuid)
                 JOIN public.profiles p ON p.id = r.source_profile_id) THEN
    RAISE EXCEPTION 'bands import: The Bangalore Blues Project profile is missing';
  END IF;

  INSERT INTO public.bands (id, slug, name, tagline, bio, genres, city, avatar_url, cover_url)
  SELECT r.id, r.slug, p.display_name, p.headline, p.bio, p.genres, p.city, p.avatar_url, p.cover_url
  FROM jsonb_to_recordset(payload) AS r(id uuid, slug text, source_profile_id uuid) JOIN public.profiles p ON p.id = r.source_profile_id
  ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, name = EXCLUDED.name, tagline = EXCLUDED.tagline,
    bio = EXCLUDED.bio, genres = EXCLUDED.genres, city = EXCLUDED.city, avatar_url = EXCLUDED.avatar_url,
    cover_url = EXCLUDED.cover_url;

  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(id uuid, slug text, source_profile_id uuid)
      JOIN public.profiles p ON p.id = r.source_profile_id JOIN public.bands t ON t.id = r.id
      WHERE (t.slug, t.name, t.tagline, t.bio, t.genres, t.city, t.avatar_url, t.cover_url)
            IS NOT DISTINCT FROM (r.slug, p.display_name, p.headline, p.bio, p.genres, p.city, p.avatar_url, p.cover_url))
     <> jsonb_array_length(payload) THEN
    RAISE EXCEPTION 'bands import: The Bangalore Blues Project differs from its profile';
  END IF;
END
$import$;

-- band_members: demo bands (6 rows)
DO $import$
DECLARE
  payload jsonb := $json$[{"band_id":"1a18f576-c433-50ae-9be7-e1d22cad05bc","username":"rahul.iyer","display_name":"Rahul Iyer","role":"owner","instrument":"Producer, guitar","since_year":2019,"sort_order":0},{"band_id":"1a18f576-c433-50ae-9be7-e1d22cad05bc","username":"ananya.sharma","display_name":"Ananya Sharma","role":"admin","instrument":"Lead vocals","since_year":2019,"sort_order":1},{"band_id":"1a18f576-c433-50ae-9be7-e1d22cad05bc","username":"meher.kaur","display_name":"Meher Kaur","role":"member","instrument":"Bass","since_year":2021,"sort_order":2},{"band_id":"1a18f576-c433-50ae-9be7-e1d22cad05bc","username":"dj.noor","display_name":"DJ Noor","role":"member","instrument":"Drums","since_year":2022,"sort_order":3},{"band_id":"71573c4d-f836-5cfe-9ba1-02b246a57353","username":"arjun.menon","display_name":"Arjun Menon","role":"owner","instrument":"Synths","since_year":2022,"sort_order":0},{"band_id":"71573c4d-f836-5cfe-9ba1-02b246a57353","username":"tanvi.rao","display_name":"Tanvi Rao","role":"member","instrument":"Live drums","since_year":2023,"sort_order":1}]$json$;
BEGIN
  -- Demo members join only a profile whose username and display name both match; the rest are reported.
  INSERT INTO public.band_members (band_id, profile_id, role, instrument, since_year, sort_order)
  SELECT r.band_id, p.id, r.role, r.instrument, r.since_year, r.sort_order
  FROM jsonb_to_recordset(payload) AS r(band_id uuid, username text, display_name text, role text, instrument text, since_year int, sort_order int) JOIN public.profiles p ON p.username = r.username AND p.display_name = r.display_name
  ON CONFLICT (band_id, profile_id) DO UPDATE SET role = EXCLUDED.role, instrument = EXCLUDED.instrument,
    since_year = EXCLUDED.since_year, sort_order = EXCLUDED.sort_order;

  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(band_id uuid, username text, display_name text, role text, instrument text, since_year int, sort_order int)
      JOIN public.profiles p ON p.username = r.username AND p.display_name = r.display_name
      JOIN public.band_members t ON t.band_id = r.band_id AND t.profile_id = p.id
      WHERE (t.role, t.instrument, t.since_year, t.sort_order) IS NOT DISTINCT FROM (r.role, r.instrument, r.since_year, r.sort_order))
     <> (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(band_id uuid, username text, display_name text, role text, instrument text, since_year int, sort_order int)
         JOIN public.profiles p ON p.username = r.username AND p.display_name = r.display_name) THEN
    RAISE EXCEPTION 'band_members import: stored rows differ from the payload';
  END IF;

  RAISE NOTICE 'band_members: demo members with no matching profile: %', (
    SELECT coalesce(string_agg(r.username || ' (' || r.display_name || ')', ', '), 'none')
    FROM jsonb_to_recordset(payload) AS r(band_id uuid, username text, display_name text, role text, instrument text, since_year int, sort_order int)
    WHERE NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.username = r.username AND p.display_name = r.display_name));
END
$import$;

-- band_members: The Bangalore Blues Project (5 rows)
DO $import$
DECLARE
  payload jsonb := $json$[{"band_id":"035dfe6b-04c5-5fcc-b41f-27e32a435685","profile_id":"388fbd0a-9c57-5f5d-84e7-45a43890c4a8","username":"arnav.desai","role":"owner","instrument":"Lead Vocalist & Slide Guitar","since_year":null,"sort_order":0},{"band_id":"035dfe6b-04c5-5fcc-b41f-27e32a435685","profile_id":"9078142e-bb3a-59c1-b330-2c9bb54af016","username":"arjun.kapoor","role":"member","instrument":"Keyboards & Hammond B3","since_year":null,"sort_order":1},{"band_id":"035dfe6b-04c5-5fcc-b41f-27e32a435685","profile_id":"41bb93a2-c008-5cd9-8527-df24dd257435","username":"zara.desai","role":"member","instrument":"Alto Saxophone","since_year":null,"sort_order":2},{"band_id":"035dfe6b-04c5-5fcc-b41f-27e32a435685","profile_id":"472ea245-75bc-42ee-8fbb-db6d571ee5d0","username":"kabirmenon","role":"member","instrument":"Double Bass","since_year":null,"sort_order":3},{"band_id":"035dfe6b-04c5-5fcc-b41f-27e32a435685","profile_id":"d7b2a092-5bed-5b7b-8789-77faad938c7c","username":"arnav.gupta","role":"member","instrument":"Drums & Percussion","since_year":null,"sort_order":4}]$json$;
BEGIN
  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(band_id uuid, profile_id uuid, username text, role text, instrument text, since_year int, sort_order int) JOIN public.profiles p
      ON p.id = r.profile_id AND p.username = r.username) <> jsonb_array_length(payload) THEN
    RAISE EXCEPTION 'band_members import: an assigned profile is missing or has another username';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_to_recordset(payload) AS r(band_id uuid, profile_id uuid, username text, role text, instrument text, since_year int, sort_order int) JOIN public.profile_business b ON b.profile_id = r.profile_id) THEN
    RAISE EXCEPTION 'band_members import: an assigned profile is a business account';
  END IF;

  INSERT INTO public.band_members (band_id, profile_id, role, instrument, since_year, sort_order)
  SELECT r.band_id, r.profile_id, r.role, r.instrument, r.since_year, r.sort_order FROM jsonb_to_recordset(payload) AS r(band_id uuid, profile_id uuid, username text, role text, instrument text, since_year int, sort_order int)
  ON CONFLICT (band_id, profile_id) DO UPDATE SET role = EXCLUDED.role, instrument = EXCLUDED.instrument,
    since_year = EXCLUDED.since_year, sort_order = EXCLUDED.sort_order;

  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(band_id uuid, profile_id uuid, username text, role text, instrument text, since_year int, sort_order int) JOIN public.band_members t
      ON t.band_id = r.band_id AND t.profile_id = r.profile_id
      WHERE (t.role, t.instrument, t.since_year, t.sort_order) IS NOT DISTINCT FROM (r.role, r.instrument, r.since_year, r.sort_order))
     <> jsonb_array_length(payload) THEN
    RAISE EXCEPTION 'band_members import: stored rows differ from the payload';
  END IF;
END
$import$;

-- band_events: demo bands (4 rows)
DO $import$
DECLARE
  payload jsonb := $json$[{"id":"a9e71aa6-acfc-560c-8bd8-6538048ec94f","band_id":"1a18f576-c433-50ae-9be7-e1d22cad05bc","title":"Monsoon Sessions","venue":"antiSOCIAL","city":"Mumbai","event_date":"2026-09-19","event_time":"21:00","date_precision":"day","status":"confirmed","ticket_note":"Tickets live","sort_order":0},{"id":"079e52ca-03d5-5536-a249-c79bf7ccd550","band_id":"1a18f576-c433-50ae-9be7-e1d22cad05bc","title":"Bengaluru run","venue":"Fandom","city":"Bengaluru","event_date":"2026-10-02","event_time":"20:30","date_precision":"day","status":"hold","ticket_note":null,"sort_order":1},{"id":"bedb48d2-26e2-5c72-8c03-3286e093f748","band_id":"1a18f576-c433-50ae-9be7-e1d22cad05bc","title":"Kala Ghoda Festival","venue":"Amphitheatre","city":"Mumbai","event_date":"2026-02-01","event_time":null,"date_precision":"month","status":null,"ticket_note":null,"sort_order":2},{"id":"168e1881-63a3-58f1-b441-24ab463c5243","band_id":"71573c4d-f836-5cfe-9ba1-02b246a57353","title":"Basement Series","venue":"Bflat","city":"Bengaluru","event_date":"2026-09-24","event_time":"20:00","date_precision":"day","status":"confirmed","ticket_note":null,"sort_order":0}]$json$;
BEGIN
  INSERT INTO public.band_events (id, band_id, title, venue, city, event_date, event_time, date_precision, status, ticket_note, sort_order)
  SELECT r.id, r.band_id, r.title, r.venue, r.city, r.event_date, r.event_time, r.date_precision, r.status, r.ticket_note, r.sort_order FROM jsonb_to_recordset(payload) AS r(id uuid, band_id uuid, title text, venue text, city text, event_date date, event_time time, date_precision text, status text, ticket_note text, sort_order int)
  ON CONFLICT (id) DO UPDATE SET band_id = EXCLUDED.band_id, title = EXCLUDED.title, venue = EXCLUDED.venue, city = EXCLUDED.city, event_date = EXCLUDED.event_date, event_time = EXCLUDED.event_time, date_precision = EXCLUDED.date_precision, status = EXCLUDED.status, ticket_note = EXCLUDED.ticket_note, sort_order = EXCLUDED.sort_order;

  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(id uuid, band_id uuid, title text, venue text, city text, event_date date, event_time time, date_precision text, status text, ticket_note text, sort_order int) JOIN public.band_events t ON t.id = r.id
      WHERE (t.id, t.band_id, t.title, t.venue, t.city, t.event_date, t.event_time, t.date_precision, t.status, t.ticket_note, t.sort_order) IS NOT DISTINCT FROM (r.id, r.band_id, r.title, r.venue, r.city, r.event_date, r.event_time, r.date_precision, r.status, r.ticket_note, r.sort_order))
     <> jsonb_array_length(payload) THEN
    RAISE EXCEPTION 'band_events import: stored rows differ from the payload';
  END IF;
END
$import$;

-- band_events: The Bangalore Blues Project, from its profile (3 rows)
DO $import$
DECLARE
  payload jsonb := $json$[{"id":"25321640-045e-5909-ad98-f46d8416ed34","band_id":"035dfe6b-04c5-5fcc-b41f-27e32a435685","source_event_id":"a407c423-e464-51be-b78b-0512faee6418"},{"id":"cf61e70a-57b1-51ea-8ee0-8f2a5dbfe8c3","band_id":"035dfe6b-04c5-5fcc-b41f-27e32a435685","source_event_id":"828db50e-5fc7-576b-804c-4014fd9d5519"},{"id":"242a2073-a3ea-58b4-b2e5-f90638a70f2c","band_id":"035dfe6b-04c5-5fcc-b41f-27e32a435685","source_event_id":"2634c7b4-9376-5977-8c8a-c1049e363bb4"}]$json$;
BEGIN
  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(id uuid, band_id uuid, source_event_id uuid) JOIN public.profile_events e ON e.id = r.source_event_id)
     <> jsonb_array_length(payload) THEN
    RAISE EXCEPTION 'band_events import: a show of The Bangalore Blues Project profile is missing';
  END IF;

  -- The profile's shows are copied, not moved: profile_events keeps its rows.
  INSERT INTO public.band_events (id, band_id, title, venue, event_date, date_precision, sort_order)
  SELECT r.id, r.band_id, e.title, e.venue_name, e.event_date, 'day', e.sort_order
  FROM jsonb_to_recordset(payload) AS r(id uuid, band_id uuid, source_event_id uuid) JOIN public.profile_events e ON e.id = r.source_event_id
  ON CONFLICT (id) DO UPDATE SET band_id = EXCLUDED.band_id, title = EXCLUDED.title, venue = EXCLUDED.venue,
    event_date = EXCLUDED.event_date, date_precision = EXCLUDED.date_precision, sort_order = EXCLUDED.sort_order;

  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(id uuid, band_id uuid, source_event_id uuid) JOIN public.profile_events e ON e.id = r.source_event_id
      JOIN public.band_events t ON t.id = r.id
      WHERE (t.band_id, t.title, t.venue, t.city, t.event_date, t.event_time, t.date_precision, t.status, t.ticket_note, t.sort_order)
            IS NOT DISTINCT FROM (r.band_id, e.title, e.venue_name, NULL::text, e.event_date, NULL::time, 'day', NULL::text, NULL::text, e.sort_order))
     <> jsonb_array_length(payload) THEN
    RAISE EXCEPTION 'band_events import: stored shows differ from the profile';
  END IF;
END
$import$;

-- band_releases (3 rows)
DO $import$
DECLARE
  payload jsonb := $json$[{"id":"5cff6f78-d042-579e-ac50-da394c2e7707","band_id":"1a18f576-c433-50ae-9be7-e1d22cad05bc","title":"Paper Kites","kind":"ep","release_year":2025,"cover_url":"https://images.unsplash.com/photo-1493225457124-a3eb161ffa5f?auto=format&fit=crop&w=500&q=80","sort_order":0},{"id":"d6196139-7841-58f3-bd5d-fc81af9463d3","band_id":"1a18f576-c433-50ae-9be7-e1d22cad05bc","title":"Bandra East, Live","kind":"live","release_year":2024,"cover_url":"https://images.unsplash.com/photo-1459749411175-04bf5292ceea?auto=format&fit=crop&w=500&q=80","sort_order":1},{"id":"b75bc3d8-39e2-506f-aabe-755b48e78e0a","band_id":"71573c4d-f836-5cfe-9ba1-02b246a57353","title":"Signal Garden","kind":"single","release_year":2025,"cover_url":"https://images.unsplash.com/photo-1487180144351-b8472da7d491?auto=format&fit=crop&w=500&q=80","sort_order":0}]$json$;
BEGIN
  INSERT INTO public.band_releases (id, band_id, title, kind, release_year, cover_url, sort_order)
  SELECT r.id, r.band_id, r.title, r.kind, r.release_year, r.cover_url, r.sort_order FROM jsonb_to_recordset(payload) AS r(id uuid, band_id uuid, title text, kind text, release_year int, cover_url text, sort_order int)
  ON CONFLICT (id) DO UPDATE SET band_id = EXCLUDED.band_id, title = EXCLUDED.title, kind = EXCLUDED.kind, release_year = EXCLUDED.release_year, cover_url = EXCLUDED.cover_url, sort_order = EXCLUDED.sort_order;

  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(id uuid, band_id uuid, title text, kind text, release_year int, cover_url text, sort_order int) JOIN public.band_releases t ON t.id = r.id
      WHERE (t.id, t.band_id, t.title, t.kind, t.release_year, t.cover_url, t.sort_order) IS NOT DISTINCT FROM (r.id, r.band_id, r.title, r.kind, r.release_year, r.cover_url, r.sort_order))
     <> jsonb_array_length(payload) THEN
    RAISE EXCEPTION 'band_releases import: stored rows differ from the payload';
  END IF;
END
$import$;
